    hits.repetition = repeats;
    raw += Math.min(repeats, 6) * 2;
  }

  // Squash to a 0-10 scale for easy ranking alongside the judge.
  const score = Math.min(10, Math.round((raw / 4) * 10) / 10);
  return { score, raw, hits };
}

